document.addEventListener('click', function (event) {
  const wrapper = event.target.closest('.crown-date-field');

  if (!wrapper) {
    return;
  }

  const input = wrapper.querySelector('input[type="date"]');

  if (!input) {
    return;
  }

  input.focus();

  if (typeof input.showPicker === 'function') {
    input.showPicker();
  }
});

